#!/usr/bin/env python3
"""Compute ground truth for CSX-082_Q1 from local Storm Boris records."""

from __future__ import annotations

import json
import re
from html.parser import HTMLParser
from pathlib import Path
from typing import Any


TASK_ID = "CSX-082_Q1"
EVENT_ID = "CSX-082"
ROOT = Path(__file__).resolve().parents[3]
PACKAGE = ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_003_Locked_event_anchor_Storm_Boris_Central_and_Eastern_Europe_floods.json",
    "data/other/other_001_ECMWF_-_Storm_Boris_and_European_flooding_September_2024.html",
]


class TextExtractor(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self._tag: str | None = None
        self._parts: list[str] = []
        self.blocks: list[str] = []

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag in {"p", "h1", "h2", "h3", "li", "em"}:
            self._tag = tag
            self._parts = []

    def handle_endtag(self, tag: str) -> None:
        if self._tag == tag:
            text = " ".join("".join(self._parts).split())
            if text:
                self.blocks.append(text)
            self._tag = None

    def handle_data(self, data: str) -> None:
        if self._tag:
            self._parts.append(data)


def read_json(rel_path: str) -> Any:
    return json.loads((PACKAGE / rel_path).read_text(encoding="utf-8-sig"))


def read_html_text(rel_path: str) -> str:
    parser = TextExtractor()
    parser.feed((PACKAGE / rel_path).read_text(encoding="utf-8", errors="ignore"))
    return "\n".join(parser.blocks)


def require(pattern: str, text: str, flags: int = re.IGNORECASE) -> re.Match[str]:
    match = re.search(pattern, text, flags)
    if not match:
        raise RuntimeError(f"Missing required text pattern: {pattern}")
    return match


def split_countries(text: str) -> list[str]:
    return [part.strip() for part in text.replace(" and ", ", ").split(",") if part.strip()]


def extract_report_claims(rel_path: str) -> dict[str, Any]:
    text = read_html_text(rel_path)
    country_text = require(
        r"severe flooding in parts of (Austria, Czechia, Slovakia, Poland, Romania and Hungary)",
        text,
    ).group(1)
    return {
        "countries": split_countries(country_text),
        "reported_deaths": int(require(r"loss of ([0-9]+) lives", text).group(1)),
        "three_day_rain_mm": int(require(r"A three-day total of ([0-9]+) mm", text).group(1)),
        "romania_flash_deaths": 7
        if require(r"seven fatalities due to short duration extreme rainfall", text)
        else None,
        "first_severe_signal_run": require(
            r"first very strong signal.*?from the ([0-9]+ September [0-9]+ UTC) run",
            text,
            flags=re.IGNORECASE | re.DOTALL,
        ).group(1),
        "oder_return_period_years_min": int(
            require(
                r"Oder River basin.*?at least a ([0-9]+)-year return period",
                text,
                flags=re.IGNORECASE | re.DOTALL,
            ).group(1)
        ),
        "upper_danube_signal_run": require(
            r"upper Danube .*? with the ([0-9]+ September [0-9]+ UTC) forecast run",
            text,
            flags=re.IGNORECASE | re.DOTALL,
        ).group(1),
        "river_length_gt2x_aam_km": int(
            require(r"beyond twice the average annual maximum along ([0-9,]+) km of rivers", text)
            .group(1)
            .replace(",", "")
        ),
    }


def main() -> None:
    event = read_json(SOURCE_FILES[0])
    anchor = read_json(SOURCE_FILES[1])
    report = extract_report_claims(SOURCE_FILES[2])

    if event["package_id"] != EVENT_ID or event["hazard_family"] != "river_coastal_flood":
        raise RuntimeError("Unexpected event metadata for CSX-082_Q1")

    rain_pass = report["three_day_rain_mm"] >= 300
    oder_pass = report["oder_return_period_years_min"] >= 20
    river_pass = report["river_length_gt2x_aam_km"] >= 5000
    flash_share = report["romania_flash_deaths"] / report["reported_deaths"]
    flash_only_rejected = flash_share < (1 / 3)
    score = sum([rain_pass, oder_pass, river_pass, flash_only_rejected])
    answer = "basin_river_flood_dominant" if score == 4 else "not_basin_river_flood_dominant"

    output = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "target_family": "candidate_explanation_score_ledger",
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "primary_gt": {
            "answer": answer,
            "score": score,
            "three_day_rain_mm": report["three_day_rain_mm"],
            "oder_rp_years_min": report["oder_return_period_years_min"],
            "river_length_gt2x_aam_km": report["river_length_gt2x_aam_km"],
            "romania_fatality_share": round(flash_share, 3),
            "flash_only_test": "rejected",
            "decision_rule": "all four ledger tests pass",
        },
        "key_values": {
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_window": anchor["temporal_window"],
            "countries_named_in_report": report["countries"],
            "reported_deaths": report["reported_deaths"],
            "romania_flash_deaths": report["romania_flash_deaths"],
            "flash_fatality_share_exact": flash_share,
            "thresholds": {
                "three_day_rain_mm_min": 300,
                "oder_return_period_years_min": 20,
                "river_length_gt2x_aam_km_min": 5000,
                "flash_fatality_share_max_for_flash_only": 1 / 3,
            },
            "forecast_timing": {
                "first_severe_signal_run": report["first_severe_signal_run"],
                "upper_danube_signal_run": report["upper_danube_signal_run"],
            },
            "ledger_tests": {
                "extreme_multiday_rain": rain_pass,
                "severe_oder_threshold": oder_pass,
                "widespread_river_amplification": river_pass,
                "flash_only_explanation_rejected": flash_only_rejected,
            },
            "tolerances": {
                "three_day_rain_mm": 0,
                "oder_rp_years_min": 0,
                "river_length_gt2x_aam_km": 0,
                "romania_fatality_share": 0.005,
                "score": 0,
            },
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "Final ledger result",
                    "points": 4,
                    "description": "Returns the label basin_river_flood_dominant with a score of 4 out of 4.",
                    "partial_credit": "Award 2 points for the right label with no score or a score off by one; 1 point for a vague river-flood conclusion.",
                },
                {
                    "name": "Rainfall threshold test",
                    "points": 3,
                    "description": "Uses the 442 mm three-day rainfall value and correctly marks the 300 mm threshold test as passed.",
                    "partial_credit": "Award 1-2 points for a correct extreme-rain claim with a missing threshold, wrong unit, or minor value error.",
                },
                {
                    "name": "Oder severity test",
                    "points": 3,
                    "description": "Uses the at-least-20-year Oder River basin signal and correctly marks the return-period threshold test as passed.",
                    "partial_credit": "Award 1-2 points for recognizing severe Oder flooding but omitting the at-least qualifier or threshold comparison.",
                },
                {
                    "name": "River amplification test",
                    "points": 3,
                    "description": "Uses 8,500 km of rivers beyond twice average annual maximum flow and correctly marks the 5,000 km extent test as passed.",
                    "partial_credit": "Award 1-2 points for mentioning widespread high flows with an incomplete value or comparison.",
                },
                {
                    "name": "Flash-only rejection",
                    "points": 3,
                    "description": "Computes 7 divided by 27 as about 0.259 and rejects a flash-flood-only explanation because it is below one third.",
                    "partial_credit": "Award 1-2 points for using the 7 and 27 counts but missing the ratio or the one-third comparison.",
                },
                {
                    "name": "Formula and threshold clarity",
                    "points": 2,
                    "description": "States or clearly applies the four pass/fail tests and the all-four-pass decision rule.",
                    "partial_credit": "Award 1 point if the tests are implicit but the arithmetic mostly supports the final label.",
                },
                {
                    "name": "Concise constrained output",
                    "points": 2,
                    "description": "Returns a compact JSON-style answer with the requested fields and no action advice or broad event essay.",
                    "partial_credit": "Award 1 point for a readable answer that has minor formatting problems or extra prose but remains scoreable.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
            "notes": "Ground truth is regenerated from package metadata, the locked event anchor, and the ECMWF Storm Boris report.",
        },
    }

    (Path(__file__).resolve().parent / "computed_gt.json").write_text(
        json.dumps(output, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
